import type { ComponentProps, ReactNode } from "react";
import { ActivityIndicator, Pressable, TextInput, View } from "react-native";
import { Text } from "../../primitives/text/text.js";
import { cn } from "../../lib/utils.js";

/** Props for {@link Composer}. */
export interface ComposerProps extends Omit<ComponentProps<typeof TextInput>, "onSubmitEditing"> {
	/** Current draft text. */
	value: string;
	/** Called with the new draft on every edit. */
	onChangeText: (next: string) => void;
	/** Called with the trimmed draft when the user sends. */
	onSubmit: (message: string) => void;
	/** Block input and the send control while a reply streams. */
	busy?: boolean;
	/** Accessible name for the send control. */
	sendLabel?: string;
	/**
	 * Glyph rendered inside the send button. Defaults to an upward arrow.
	 *
	 * Pass your own icon here — passing it as a child of `<Composer>` would
	 * land it on the underlying `TextInput`, which is not where it belongs.
	 */
	sendIcon?: ReactNode;
	/** Additional classes on the surrounding bar. */
	className?: string;
}

/**
 * The chat input bar: a growing text field plus a send control.
 *
 * Send is an explicit button rather than a Return key. On a phone Return
 * should insert a newline in a multi-line field, and a visible control is
 * also the only send affordance a screen-reader user can find.
 * @param props - {@link ComposerProps}
 * @returns The composer bar
 * @example
 * ```tsx
 * <Composer
 *   value={draft}
 *   onChangeText={setDraft}
 *   onSubmit={send}
 *   busy={isStreaming}
 * />
 * ```
 */
export function Composer({
	value,
	onChangeText,
	onSubmit,
	busy = false,
	sendLabel = "Send message",
	sendIcon,
	placeholder = "Message…",
	className,
	...props
}: ComposerProps) {
	const trimmed = value.trim();
	const canSend = trimmed.length > 0 && !busy;

	return (
		<View
			className={cn(
				"flex-row items-end gap-2 border-t border-border bg-background px-4 py-3",
				className,
			)}
		>
			<TextInput
				multiline
				value={value}
				onChangeText={onChangeText}
				editable={!busy}
				placeholder={placeholder}
				textAlignVertical="top"
				className={cn(
					"max-h-32 min-h-10 flex-1 rounded-2xl border border-input bg-background px-4 py-2 text-base leading-5 text-foreground",
					"placeholder:text-muted-foreground",
					busy && "opacity-50",
				)}
				{...props}
			/>
			<Pressable
				role="button"
				aria-label={sendLabel}
				aria-disabled={!canSend}
				disabled={!canSend}
				onPress={() => {
					if (canSend) onSubmit(trimmed);
				}}
				className={cn(
					"h-10 w-10 items-center justify-center rounded-full bg-primary",
					!canSend && "opacity-50",
				)}
			>
				{/*
				 * A glyph whenever the button is not busy. Rendering only the
				 * spinner left the send control as a blank primary-coloured
				 * disc in its usable state, and gave it a visible symbol only
				 * while it was disabled.
				 */}
				{busy ? (
					<ActivityIndicator size="small" className="text-primary-foreground" />
				) : (
					(sendIcon ?? <Text className="text-lg leading-none text-primary-foreground">↑</Text>)
				)}
			</Pressable>
		</View>
	);
}

import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import { Text as RNText } from "react-native";
import { useTextClass } from "../../lib/text-context.js";
import { cn } from "../../lib/utils.js";

/**
 * Typographic scale for native text.
 *
 * Mirrors the web docs' heading and body styles, minus anything that needs a
 * DOM: no `scroll-m-*`, no `text-balance`, no `select-text`.
 */
export const textVariants = cva("text-base text-foreground", {
	variants: {
		variant: {
			default: "",
			h1: "text-4xl font-extrabold tracking-tight",
			h2: "text-3xl font-semibold tracking-tight",
			h3: "text-2xl font-semibold tracking-tight",
			h4: "text-xl font-semibold tracking-tight",
			p: "leading-7",
			lead: "text-xl text-muted-foreground",
			large: "text-lg font-semibold",
			small: "text-sm font-medium leading-none",
			muted: "text-sm text-muted-foreground",
			code: "rounded bg-muted px-[0.3rem] py-[0.2rem] font-mono text-sm font-semibold",
		},
	},
	defaultVariants: {
		variant: "default",
	},
});

type TextVariant = NonNullable<VariantProps<typeof textVariants>["variant"]>;

/** Variants that read as headings to VoiceOver and TalkBack. */
const HEADING_VARIANTS: ReadonlySet<TextVariant> = new Set<TextVariant>(["h1", "h2", "h3", "h4"]);

/**
 * Props for {@link Text}. `ref` comes with the React Native `Text` props and
 * reaches the host element (React 19 — no forwardRef).
 */
export type TextProps = ComponentProps<typeof RNText> & VariantProps<typeof textVariants>;

/**
 * Themed text with a typographic scale and parent-driven class inheritance.
 *
 * React Native text does not inherit colour or size from a `View`, so
 * containers like `Button`, `Card` and `Badge` publish the classes they want
 * their labels to carry through `TextClassContext`; this component reads
 * them and lets an explicit `className` win.
 * @param props - {@link TextProps}
 * @returns A React Native `Text` element
 * @example
 * ```tsx
 * <Text variant="h2">Settings</Text>
 * <Text variant="muted">Manage your account preferences.</Text>
 * ```
 */
export function Text({ className, variant = "default", ...props }: TextProps) {
	const inherited = useTextClass();
	const isHeading = variant !== null && HEADING_VARIANTS.has(variant);
	return (
		<RNText
			className={cn(textVariants({ variant }), inherited, className)}
			role={isHeading ? "heading" : undefined}
			{...props}
		/>
	);
}

import { createContext, useContext } from "react";

/**
 * Class names a parent wants applied to the `<Text>` elements inside it.
 *
 * React Native text does not inherit colour or size from its container the
 * way DOM text does, so a `Button` cannot make its label
 * `text-primary-foreground` by styling itself. Instead it provides that
 * class here and `Text` reads it. Same pattern React Native Reusables
 * uses; kept as a tiny shared module so every component agrees on it.
 */
export const TextClassContext = createContext<string | undefined>(undefined);

/**
 * Read the class names the nearest text-styling ancestor provided.
 * @returns The inherited class string, or undefined outside any provider
 */
export function useTextClass(): string | undefined {
	return useContext(TextClassContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind-aware conflict resolution.
 *
 * Deliberately a copy of the web helper rather than an import from
 * `@hex-core/components`: that package is React DOM, and `hex add` ships
 * this file into the consumer's project alongside each component anyway.
 * NativeWind's platform prefixes (`ios:`, `android:`, `native:`) are
 * unknown to tailwind-merge and pass through untouched.
 * @param inputs - Class values (strings, arrays, conditionals) to merge
 * @returns The merged class string with later Tailwind utilities winning
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
